insert into enem.questions (id, year, number, page, theme, stem, options) values
('2020-6',2020,6,6,'Funções da linguagem','Os processos de interação comunicativa preveem a presença ativa de múltiplos elementos da comunicação, entre os quais se destacam as funções da linguagem. Nesse fragmento, a função da linguagem predominante é a','["emotiva, porque o poeta expõe os sentimentos de angústia que o levaram à criação poética.", "referencial, porque o texto informa sobre a origem do nome empregado em um famoso poema de Bandeira.", "metalinguística, porque o poeta tece comentários sobre a gênese e o processo de escrita de um de seus poemas.", "poética, porque o texto aborda os elementos estéticos de um dos poemas mais conhecidos de Bandeira.", "apelativa, porque o poeta tenta convencer os leitores sobre sua dificuldade de compor um poema."]'::jsonb),
('2020-7',2020,7,6,'Variação linguística','A frase, título do filme, reproduz uma variedade linguística recorrente na fala de muitos brasileiros. Essa estrutura caracteriza-se pelo(a)','["uso de uma marcação temporal.", "imprecisão do referente de pessoa.", "organização interrogativa da frase.", "utilização de um verbo de ação.", "apagamento de uma preposição."]'::jsonb),
('2020-9',2020,9,7,'Variação linguística','A leitura do texto permite ao leitor entrar em contato com','["registros do inventário do português brasileiro.", "justificativas da variedade linguística do país.", "influências da fala do nordestino no uso da língua.", "explorações do falar de um grupo social específico.", "representações da mudança linguística do português."]'::jsonb),
('2020-10',2020,10,7,'Humor e metalinguagem','As aspas sinalizam expressões metafóricas empregadas intencionalmente pelo autor do texto para','["imprimir um tom irônico à reportagem.", "incorporar citações de especialistas à reportagem.", "atribuir maior valor aos metais, objeto da reportagem.", "esclarecer termos científicos empregados na reportagem.", "marcar a apropriação de termos de outra ciência pela reportagem."]'::jsonb),
('2020-13',2020,13,8,'Esporte e mídia','A inter-relação entre tecnologia e sociedade tem estimulado a criação de aplicativos. Nesse texto, isso é percebido pelo desenvolvimento de aplicativos para','["organização de eventos de competições esportivas.", "agendamento de viagens para eventos de esporte amador.", "mapeamento dos interesses dos praticantes acerca dos esportes.", "identificação da escassez de espaços para a vivência dos esportes.", "formação de grupos em comunidades virtuais para a prática esportiva."]'::jsonb),
('2020-14',2020,14,8,'Arte e identidade','A provocação desse grupo gera um debate em torno da obra de arte pelo(a)','["recusa a crenças, convicções, valores morais, estéticos e políticos na história moderna.", "frutífero arsenal de materiais e formas que se relacionam com os objetos construídos.", "economia e problemas financeiros gerados pela recessão que tiveram grande impacto no mercado.", "influência desse grupo junto aos estilos pós-modernos que surgiram nos anos 1990.", "interesse em produtos indesejáveis que revela uma consciência sustentável no mercado."]'::jsonb),
('2020-15',2020,15,9,'Esporte e mídia','',null),
('2020-16',2020,16,9,'Esporte e mídia','As reivindicações dos operários, quanto às condições aviltantes de trabalho a que são submetidos, recebem algumas tentativas de neutralização dos representantes do empregador, das quais a mais forte é o(a)','["sequência de atribuição de responsabilidades e de poder decisório a terceiros.", "solicitação em nome dos prejuízos e compromissos para entrega da obra.", "intimidação pela discreta presença de um agente de segurança na cena.", "promessa de imediato atendimento da carência sexual dos operários.", "apelo pela identificação com a empresa extensiva ao amor patriótico."]'::jsonb),
('2020-21',2020,21,11,'Arte e identidade','O fragmento faz parte da canção brasileira contemporânea e celebra a cultura popular nordestina. Nele, o artista exalta as diferentes manifestações culturais pela','["valorização do teatro, música, artesanato, literatura, dança, personagens históricos e artistas populares, compondo um tecido diversificado e enriquecedor da cultura popular como patrimônio regional e nacional.", "identificação dos lugares pernambucanos, manifestações culturais, como o bumba meu boi, as cirandas, os bonecos mamulengos e heróis locais, fazendo com que essa canção se apresente como uma referência à cultura popular nordestina.", "exaltação das raízes populares, como a poesia, a literatura de cordel e o frevo, misturadas ao erudito, como a Orquestra Armorial, compondo um rico tecido cultural, que transforma o popular em erudito.", "caracterização das festas populares como identidade cultural localizada e como representantes de uma cultura que reflete valores históricos e sociais próprios da população local.", "apresentação do Pastoril do Faceta, do maracatu, do bumba meu boi e dos autos como representação da musicalidade e do teatro popular religioso, bastante comum ao folclore brasileiro."]'::jsonb),
('2020-22',2020,22,11,'Esporte e mídia','Esse anúncio publicitário propõe soluções para um problema social recorrente, ao','["promover ações de conscientização para reduzir a violência de gênero em eventos esportivos.", "estimular o compartilhamento de políticas públicas sobre a igualdade de gênero no esporte.", "divulgar para a população as novas regras complementares para as torcidas de futebol.", "informar ao público masculino as consequências de condutas ofensivas.", "regulamentar normas de boa convivência nos estádios."]'::jsonb),
('2020-23',2020,23,12,'Humor e metalinguagem','As repetições e as frases curtas constituem procedimentos linguísticos importantes para a compreensão da temática do texto, pois','["expressam a futilidade do discurso de poder e de distinção do narrador.", "disfarçam a falta de densidade das angústias existenciais narradas.", "ironizam a valorização da cultura norte-americana pelos brasileiros.", "explicitam a ganância financeira do capitalismo contemporâneo.", "criticam os estereótipos sociais das visões de mundo elitistas."]'::jsonb),
('2020-25',2020,25,12,'Variação linguística','A obra de Joseph Kosuth data de 1965 e se constitui por uma fotografia de cadeira, uma cadeira exposta e um quadro com o verbete “Cadeira”. Trata-se de um exemplo de arte conceitual que revela o paradoxo entre verdade e imitação, já que a arte','["não é a realidade, mas uma representação dela.", "fundamenta-se na repetição, construindo variações.", "não se define, pois depende da interpretação do fruidor.", "resiste ao tempo, beneficiada por múltiplas formas de registro.", "redesenha a verdade, aproximando-se das definições lexicais."]'::jsonb),
('2020-26',2020,26,12,'Objetivo e função do texto','A realidade virtual é uma tecnologia de informação que, conforme sugere a imagem, tem como uma de suas principais funções','["promover a manipulação eficiente de conhecimentos e informações de difícil compreensão no mundo físico.", "conduzir escolhas profissionais da área de ciência da computação, oferecendo um leque de opções de atuação.", "transferir conhecimento da inteligência artificial para as áreas tradicionais, como as das ciências exatas e naturais.", "levar o ser humano a experimentar mentalmente outras realidades, para as quais é transportado sem sair de seu próprio lugar.", "delimitar tecnologias exclusivas de jogos virtuais, a fim de oferecer maior emoção ao jogador por meio de outras realidades."]'::jsonb),
('2020-27',2020,27,13,'Estratégias argumentativas','É comum coexistirem sequências tipológicas em um mesmo gênero textual. Nesse fragmento, os tipos textuais que se destacam na organização temática são','["descritivo e argumentativo, pois o enunciador detalha cada lugar por onde passa, argumentando contra a violência urbana.", "dissertativo e argumentativo, pois o enunciador apresenta seu ponto de vista sobre as notícias relativas à cidade.", "expositivo e injuntivo, pois o enunciador fala de seus estados físicos e psicológicos e interage com a mulher amada.", "narrativo e descritivo, pois o enunciador conta sobre suas andanças pelas ruas da cidade ao mesmo tempo que a descreve.", "narrativo e injuntivo, pois o enunciador ensina o interlocutor como andar pelas ruas da cidade contando sobre sua própria experiência."]'::jsonb),
('2020-29',2020,29,13,'Humor e metalinguagem','Nessa letra da canção, a suposição do último verso sinaliza a intenção do autor de','["ironizar as relações familiares modernas.", "reforçar o humor da situação representada.", "expressar perplexidade em relação ao parente.", "atribuir à criança a causa da dúvida existencial.", "questionar os lugares predeterminados da família."]'::jsonb),
('2020-32',2020,32,14,'Objetivo e função do texto','Os ditados populares são frases de sabedoria criadas pelo povo, utilizadas em várias situações da vida. Nesse texto, a personagem emprega um ditado popular com a intenção de','["criticar a natureza forte do filho.", "justificar o gênio difícil de Chiquito.", "legitimar o direito do filho à herança.", "conter o ânimo violento de Chico Lourenço.", "condenar a agressividade do marido contra o filho."]'::jsonb),
('2020-33',2020,33,15,'Arte e identidade','Considerando-se a função que os cartazes colados em postes normalmente exercem nas ruas das cidades grandes, esse texto evidencia a','["disseminação da arte poética em um veículo não convencional.", "manutenção da expectativa das pessoas ao andarem pelas ruas.", "necessidade de exposição de poemas pequenos em diferentes suportes.", "característica corriqueira do suporte lambe-lambe, muito comum nas ruas.", "exposição da beleza escondida das esquinas da cidade de Belo Horizonte."]'::jsonb),
('2020-35',2020,35,15,'Esporte e mídia','Os jogos eletrônicos presentes na cultura juvenil podem desempenhar uma relevante função na abordagem do futebol ao','["disseminarem uma modalidade, promovendo a igualdade de gênero.", "superarem jogos malsucedidos no mercado, lançados anteriormente.", "inovarem a modalidade com novas ofertas de jogos ao mercado.", "explorarem nichos de mercado antes ignorados, produzindo mais lucro.", "reforçarem estereótipos de gênero masculino ou feminino nos esportes."]'::jsonb),
('2020-38',2020,38,16,'Estratégias argumentativas','Nesse texto, busca-se seduzir o leitor por meio da exploração de uma voz externa sobre a identidade histórica do povo português. O trecho que evidencia esse procedimento argumentativo é','["“Que linda a ‘antiga, muy nobre, sempre leal e invicta’ cidade do Porto!”.", "“‘Encantei-me’, diriam eles... pelas belas paisagens, construções históricas com lindas fachadas [...]”.", "“Os tripeiros, sinônimo de portuenses, têm orgulho de sua cidade [...]”.", "“E valorizam tudo o que há de bom ali, como ‘a melhor estrada para se dirigir do mundo’ [...]”.", "“Pois na manhã do 25 de abril, dia da Revolução dos Cravos, resolvemos conhecer a tal maravilha”."]'::jsonb),
('2020-39',2020,39,17,'Estratégias argumentativas','No Hino à Bandeira, a descrição é um recurso utilizado para exaltar o símbolo nacional na medida em que','["remete a um momento futuro.", "promove a união dos cidadãos.", "valoriza os seus elementos.", "emprega termos religiosos.", "recorre à sua história."]'::jsonb),
('2020-41',2020,41,17,'Variação linguística','Nessa petição da pitoresca personagem do romance de Lima Barreto, o uso da norma-padrão justifica-se pela','["situação social de enunciação representada.", "divergência teórica entre gramáticos e literatos.", "pouca representatividade das línguas indígenas.", "atitude irônica diante da língua dos colonizadores.", "tentativa de solicitação do documento demandado."]'::jsonb),
('2020-45',2020,45,18,'Humor e metalinguagem','A tematização de Curitiba é frequente na obra de Dalton Trevisan. No fragmento, a relação do narrador com o espaço urbano é caracterizada por um olhar','["destituído de afetividade, que ironiza os costumes e as tradições da sociedade curitibana.", "marcado pela negatividade, que busca desconstruir perspectivas habituais de representação da cidade.", "carregado de melancolia, que constata a falta de identidade cultural diante dos impactos da urbanização.", "embevecido pela simplicidade do cenário, indiferente à descrição de elementos de reconhecido valor histórico.", "distanciado dos elementos narrados, que recorre ao ponto de vista do viajante como expressão de estranhamento."]'::jsonb),
('2022-8',2022,8,6,'Estratégias argumentativas','Ao divulgar a adaptação do jogo para questões relativas a ações e habilidades de mulheres notáveis, o texto busca','["contribuir para a formação cidadã dos jogadores.", "refutar modelos estereotipados de beleza e elegância.", "estimular a compradores. competitividade entre potenciais", "exemplificar estratégias de arrecadação financeira pela internet.", "desenvolver conhecimentos lúdicos específicos dos tempos atuais."]'::jsonb),
('2022-9',2022,9,6,'Estratégias argumentativas','Para convencer o público-alvo sobre a necessidade de um trânsito mais seguro, essa peça publicitária apela para o(a)','["sentimento de culpa provocado no condutor causador de acidentes.", "dano psicológico causado nas vítimas da violência nas estradas.", "importância do monitoramento do trânsito pelas autoridades competentes.", "necessidade de punição a motoristas alcoolizados envolvidos em acidentes.", "sofrimento decorrente da perda de entes queridos em acidentes automobilísticos."]'::jsonb),
('2022-10',2022,10,7,'Arte e identidade','Segundo os autores citados no texto, a expansão de possibilidades no campo das manifestações artísticas promovida pela internet pode pôr em risco o(a)','["sucesso dos artistas.", "valorização dos suportes.", "proteção da produção estética.", "modo de distribuição de obras.", "compartilhamento das obras artísticas."]'::jsonb),
('2022-15',2022,15,8,'Objetivo e função do texto','Considerando-se a função social dos posts, essa imagem evidencia a apropriação de outro gênero com o objetivo de','["promover o uso adequado de campanhas publicitárias do governo.", "divulgar o projeto sobre transparência da administração pública.", "responsabilizar o cidadão pelo controle dos gastos públicos.", "delegar a gestão de projetos de lei ao contribuinte.", "assegurar a fiscalização dos gastos públicos."]'::jsonb),
('2022-16',2022,16,9,'Objetivo e função do texto','O texto é exemplar de um gênero discursivo que cumpre a função social de','["narrar, por meio de imagem e poesia, cenas da vida das irmãs Petra e Elena.", "descrever, por meio das memórias de Petra, a separação de duas irmãs.", "sintetizar, por meio das principais cenas do filme, a história de Elena.", "lançar, por meio da história de vida do autor, um filme autobiográfico.", "avaliar, por meio de análise crítica, o filme em referência."]'::jsonb),
('2022-19',2022,19,10,'Esporte e mídia','Nesse texto, a violência no futebol está caracterizada como um(a)','["problema social localizado numa região do país.", "desafio para as torcidas organizadas dos clubes.", "reflexo da precariedade da organização social no país.", "inadequação de espaço nos estádios para receber o público.", "consequência da insatisfação dos clubes com a organização dos jogos."]'::jsonb),
('2022-20',2022,20,10,'Estratégias argumentativas','Com base na pesquisa e em uma visão ampliada de saúde, para a prática regular de exercícios ter influência significativa na saúde dos brasileiros, é necessário o desenvolvimento de estratégias que','["promovam a melhoria da aptidão física da população, dedicando-se mais tempo aos esportes.", "combatam o sedentarismo presente em parcela significativa da população no território nacional.", "facilitem a adoção da prática de exercícios, com ações relacionadas à educação e à distribuição de renda.", "auxiliem na construção de mais instalações esportivas e espaços adequados para a prática de atividades físicas e esportes.", "estimulem o incentivo fiscal para a iniciativa privada destinar verbas aos programas nacionais de promoção da saúde pelo esporte."]'::jsonb),
('2022-21',2022,21,11,'Humor e metalinguagem','Inscrito na estética romântica da literatura brasileira, o conto descortina aspectos da realidade nacional no século XIX ao','["revelar a imposição de crenças religiosas a pessoas escravizadas.", "apontar a hipocrisia do discurso conservador na defesa da escravidão.", "sugerir práticas de violência física e moral em nome do progresso material.", "relacionar o declínio da produção agrícola e comercial a questões raciais.", "ironizar o comportamento dos proprietários de terra na exploração do trabalho."]'::jsonb),
('2022-22',2022,22,11,'Objetivo e função do texto','Considerando-se o tema tecnologias e acessibilidade, os textos I e II aproximam-se porque apresentam projetos que','["garantem a igualdade entre as pessoas.", "foram criados por uma pesquisadora surda.", "tiveram origem em um curso de pós-graduação.", "estão circunscritos ao espaço institucional da escola.", "têm como objetivo a disseminação do conhecimento."]'::jsonb),
('2022-25',2022,25,12,'Esporte e mídia','O discurso da jornalista traz questionamentos sobre a relação da conquista da skatista com a','["conciliação do jornalismo com a prática do skate.", "inserção das mulheres na modalidade skate street.", "desconstrução da noção do skate como modalidade masculina.", "vanguarda de ser a atleta mais jovem a subir no pódio olímpico.", "conquista de medalha nos Jogos Olímpicos de Tóquio."]'::jsonb),
('2022-27',2022,27,13,'Objetivo e função do texto','A articulação entre os elementos verbais e os não verbais do texto tem como propósito desencadear a','["identificação de distinções entre mulheres e homens.", "revisão de representações estereotipadas de gênero.", "adoção de medidas preventivas de combate ao sexismo.", "ratificação de comportamentos femininos e masculinos.", "retomada de opiniões a respeito da diversidade dos papéis sociais."]'::jsonb),
('2022-28',2022,28,13,'Arte e identidade','O movimento de recuperação da língua patxôhã assume um caráter identitário peculiar na medida em que','["denuncia o processo de perseguição histórica sofrida pelos povos indígenas.", "conjuga o ato de resistência étnica à preservação da memória cultural.", "associa a preservação linguística ao campo da pesquisa acadêmica.", "estimula o retorno de povos indígenas a suas terras de origem.", "aumenta o número de línguas indígenas faladas no Brasil."]'::jsonb),
('2022-29',2022,29,14,'Humor e metalinguagem','No relato da visita de duas mulheres ricas a uma vidente no Morro do Castelo, a ironia — um dos traços mais representativos da narrativa machadiana — consiste no','["modo de vestir dos moradores do morro carioca.", "senso prático em relação às oportunidades de renda.", "mistério que cerca as clientes de práticas de vidência.", "misto de singeleza e astúcia dos gestos da personagem.", "interesse do narrador pelas figuras femininas ambíguas."]'::jsonb),
('2022-34',2022,34,16,'Esporte e mídia','A história da prática do mountainboard representa uma das principais marcas das atividades de aventura, caracterizada pela','["competitividade entre seus praticantes.", "atividade com padrões técnicos definidos.", "modalidade com regras predeterminadas.", "criatividade para adaptações a novos espaços.", "necessidade de espaços definidos para a sua realização."]'::jsonb),
('2022-39',2022,39,17,'Arte e identidade','De acordo com os textos I e II, compreende-se que a obra minimalista é uma','["representação da simplicidade pelo artista.", "exploração da técnica da escultura cubista.", "valorização do cotidiano por meio da geometria.", "utilização da complexidade dos elementos formais.", "combinação de formas sintéticas no espaço utilizado."]'::jsonb),
('2022-41',2022,41,18,'Objetivo e função do texto','No texto, o personagem vincula ao carnaval atitudes e reações coletivas diante das quais expressa','["consagração da alegria do povo.", "atração e asco perante atitudes libertinas.", "espanto com a quantidade de foliões nas ruas.", "intenção de confraternizar com desconhecidos.", "reconhecimento da festa como manifestação cultural."]'::jsonb),
('2022-42',2022,42,18,'Estratégias argumentativas','A partir da intimação recebida pelo filho de 9 anos, a autora faz uma reflexão em que transparece a','["lição de vida comunicada pelo tenente.", "predisposição materna para se emocionar.", "atividade política marcante da comunidade.", "resposta irônica ante o discurso da autoridade.", "necessidade de revelar seus anseios mais íntimos."]'::jsonb),
('2022-43',2022,43,19,'Estratégias argumentativas','Pela ótica do narrador, a trajetória da empregada de sua casa assume um efeito expressivo decorrente da','["citação a referências literárias tradicionais.", "alusão à inocência das crianças da época.", "estratégia de questionar a bondade humana.", "descrição detalhada das pessoas do interior.", "representação anedótica de atos de violência."]'::jsonb),
('2022-44',2022,44,19,'Arte e identidade','A instalação In absentia propõe um diálogo com o ready-made Roda de bicicleta, demonstrando que','["as formas de criticar obras do passado se repetem.", "a recorrência de temas marca a arte do final do século XX.", "as criações desmistificam os valores estéticos estabelecidos.", "o distanciamento temporal permite a transformação dos referenciais estéticos.", "o objeto ausente sugere a degradação da forma superando o modelo artístico."]'::jsonb),
('2023-6',2023,6,6,'Objetivo e função do texto','De acordo com o texto, a alteração do lema olímpico teve como objetivo a','["unificação do lema anterior ao atual.", "aproximação entre o lema olímpico e o COI.", "junção do lema olímpico com os princípios esportivos.", "associação entre o lema olímpico e a cooperatividade.", "vinculação entre o lema olímpico e os eventos atléticos."]'::jsonb),
('2023-7',2023,7,6,'Arte e identidade','Nesse texto, os recursos expressivos usados pela narradora','["revelam as marcas da violência de raça e de gênero na construção da identidade.", "questionam o pioneirismo do estado do Ceará no enfrentamento à escravidão.", "reproduzem padrões estéticos em busca da valorização da autoestima feminina.", "sugerem uma atmosfera onírica alinhada ao desejo de resgate da espiritualidade.", "mimetizam, na paisagem, os corpos transformados pela violência da escravidão."]'::jsonb),
('2023-8',2023,8,6,'Variação linguística','O texto de Agualusa tematiza o preconceito em relação ao português brasileiro. Com base no trecho citado pelo autor, infere-se que esse preconceito se deve','["à dificuldade de consolidação da literatura brasileira em outros países.", "aos diferentes graus de instrução formal entre os falantes de língua portuguesa.", "à existência de uma língua ideal que alguns falantes lusitanos creem ser a falada em Portugal.", "ao intercâmbio cultural que ocorre entre os povos dos diferentes países de língua portuguesa.", "à distância territorial entre os falantes do português que vivem em Portugal e no Brasil."]'::jsonb),
('2023-11',2023,11,7,'Estratégias argumentativas','Considerando os procedimentos argumentativos utilizados, infere-se que o objetivo desse texto é','["enumerar as causas determinantes da violência no trânsito.", "contextualizar a campanha de advertência no cenário mundial.", "divulgar dados numéricos alarmantes sobre acidentes de trânsito.", "sensibilizar o público para a importância de uma direção responsável.", "restringir os problemas da violência no trânsito a aspectos emocionais."]'::jsonb),
('2023-15',2023,15,9,'Arte e identidade','A perda dos registros linguísticos no incêndio do Museu Nacional tem impacto potencializado, uma vez que','["exige a retomada das pesquisas por especialistas de diferentes áreas.", "representa danos irreparáveis à memória e à identidade nacionais.", "impossibilita o surgimento de novas pesquisas na área.", "resulta na extinção da cultura de povos originários.", "inviabiliza o estudo da língua do povo Tikuna."]'::jsonb),
('2023-16',2023,16,10,'Variação linguística','Nesse texto, a Língua Brasileira de Sinais (Libras)','["passa por fenômenos de variação linguística como qualquer outra língua.", "apresenta variações regionais, assumindo novo sentido para algumas palavras.", "sofre mudança estrutural motivada pelo uso de sinais diferentes para algumas palavras.", "diferencia-se em todo o Brasil, desenvolvendo cada região a sua própria língua de sinais.", "é ininteligível para parte dos usuários em razão das mudanças de sinais motivadas geograficamente."]'::jsonb),
('2023-17',2023,17,10,'Objetivo e função do texto','O uso não padrão dos colchetes para nomear a revista atribui-lhes uma nova função e está correlacionado ao(à)','["perfil de público-alvo, constituído por leitores exigentes e especializados em leitura acadêmica.", "propósito do editor, chamando a atenção para o rigor normativo nos textos da revista.", "exclusividade na seleção temática, direcionada para a área das ciências humanas.", "identidade da revista, voltada para a recepção e a promoção de ideias circulantes em livros.", "padrão editorial dos artigos, organizados em torno de uma proposta de design inovador."]'::jsonb),
('2023-18',2023,18,10,'Objetivo e função do texto','Embora oriundas de momentos históricos diferentes, essas letras de canção têm em comum a','["referência às cores como elemento de crítica a hábitos contemporâneos.", "percepção da profusão de informações gerada pela tecnologia.", "contraposição entre os vícios e as virtudes da vida moderna.", "busca constante pela liberdade de expressão individual.", "crítica à finalidade comercial das notícias."]'::jsonb),
('2023-19',2023,19,11,'Estratégias argumentativas','E criticar o obstáculo promovido pelos usos especializados da linguagem. O uso de citação e de dados estatísticos nesse texto tem o objetivo de','["ressaltar a importância da poesia para denunciar a morte de negros, que cresce a cada dia.", "destacar o crescimento exponencial da temática do preconceito na produção literária no Brasil.", "demonstrar o incremento no quantitativo de expressões artísticas na discussão de problemas sociais.", "evidenciar argumentos que reforçam a ideia de que os negros são vítimas em potencial da violência.", "salientar o aumento da participação de jovens nos movimentos de resistência na área da cultura."]'::jsonb),
('2023-21',2023,21,11,'Variação linguística','Ao registrarem usos regionais de termos da área médica, pesquisadores','["apontaram erros motivados pelo desconhecimento da variedade linguística local.", "explicaram problemas provocados pela incapacidade de comunicação.", "descobriram novos sintomas de doenças existentes na comunidade.", "propiciaram melhor compreensão dos sintomas dos pacientes.", "divulgaram um novo rol de doenças características da localidade."]'::jsonb),
('2023-22',2023,22,12,'Arte e identidade','A representação da mulher apresentada no Texto I pode ser explicada pelo Texto II no que diz respeito à(às)','["censura a formas de expressão femininas.", "ausência da figura feminina na vida pública.", "construções imaginárias cristalizadas na sociedade.", "limitações inerentes às figuras femininas e masculinas.", "dificuldade na atribuição de papéis masculinos e femininos."]'::jsonb),
('2023-23',2023,23,12,'Objetivo e função do texto','Esse anúncio publicitário, veiculado durante o contexto da pandemia de covid-19, tem por finalidade','["divulgar o canal telefônico de atendimento a casos de violência contra a mulher.", "informar sobre a atuação de uma entidade defensora da mulher vítima de violência.", "evidenciar o trabalho da Defensoria Pública em relação ao problema do abuso contra a mulher.", "alertar a sociedade sobre o aumento da violência contra a mulher em decorrência do coronavírus.", "incentivar o público feminino a denunciar crimes de violência contra a mulher durante o período de isolamento."]'::jsonb),
('2023-28',2023,28,13,'Funções da linguagem','A função emotiva presente no poema cumpre o propósito do eu lírico de','["revelar as desilusões amorosas.", "refletir sobre a censura à sua voz.", "expressar a dificuldade de comunicação.", "ressaltar a existência de pressões externas.", "manifestar as dores do processo de criação."]'::jsonb),
('2023-33',2023,33,15,'Arte e identidade','TEXTO I Quase cinquenta obras de Lasar Segall foram confiscadas pelo regime totalitário alemão na primeira metade do século XX, entre elas a obra Eternos caminhantes, considerada degenerada por','["representar uma estética tida como inconveniente para o ideário político vigente.", "manifestar um posicionamento político-cultural concebido por grupos de oposição.", "expressar a cultura artística por meio da representação parcial do corpo humano.", "apresentar uma composição que antecipa o imaginário artístico germânico.", "estimular discussões sobre o papel da arte na construção coletiva de cultura."]'::jsonb),
('2023-34',2023,34,15,'Arte e identidade','No diálogo que estabelece com religiões afro-brasileiras, sintetizado na descrição e na imagem do espetáculo, a dança exprime uma','["crítica aos movimentos padronizados do balé clássico.", "representação contemporânea de rituais ancestrais extintos.", "reelaboração estética erudita de práticas religiosas populares.", "releitura irônica da atmosfera mística presente no culto a entidades.", "oposição entre o resgate de tradições e a efemeridade da vida humana."]'::jsonb),
('2023-35',2023,35,16,'Esporte e mídia','O contexto em que o esporte eletrônico é apresentado no texto demonstra o(a)','["condição favorável à expansão dessa modalidade.", "promoção dessa prática por jogadores profissionais.", "impulsionamento de um processo de marketing.", "favorecimento de fabricantes dos jogos.", "modificação da audiência televisiva."]'::jsonb),
('2023-36',2023,36,16,'Objetivo e função do texto','A manifestação do Marabaixo se constituiu em expressão de arte e cultura, exercendo função de','["ressignificar episódios dramáticos em novas práticas culturais.", "adaptar coreografias como imitação dos movimentos do mar.", "lembrar dos mortos no passado escravista como forma de lamento.", "perpetuar uma narrativa de apagamento dos fatos históricos traumáticos.", "ritualizar a passagem de atos fúnebres nas produções coletivas com espírito festivo."]'::jsonb),
('2023-37',2023,37,16,'Objetivo e função do texto','O artista goiano Wolney Fernandes busca expor seu trabalho por meio de plataformas virtuais com o objetivo de','["dar suporte à técnica de colagem em Artes Visuais, contornando dificuldades práticas.", "aproximar-se da estética visual própria da editoração de obras artísticas, como capas de livros.", "oferecer uma vitrine internacional para sua produção artística, a fim de dar mais visibilidade a suas obras.", "enfatizar o caráter original e inovador de suas criações artísticas, diferenciando-se das artes tradicionais.", "trazer um sentido tecnológico às suas colagens, uma vez que as imagens artísticas são recorrentes nas redes sociais."]'::jsonb),
('2023-38',2023,38,16,'Arte e identidade','O movimento rap dos povos originários do Brasil revela o(a)','["fusão de manifestações artísticas urbanas contemporâneas com a cultura indígena.", "contraposição das temáticas socioambientais indígenas às questões urbanas.", "rejeição da indústria radiofônica às músicas indígenas.", "distanciamento da realidade social indígena.", "estímulo ao estudo da poesia indígena."]'::jsonb),
