('2024-45',2024,45,18,'Humor e metalinguagem','Ao abordar a relação dos memes com a educação, a reportagem sustenta uma crítica à','["falta de fiscalização no uso de aplicativos de mensagens por crianças.", "divulgação de informação manipulada em postagens virtuais.", "utilização de ferramentas digitais no trabalho educacional.", "exploração de conteúdos humorísticos nas mídias sociais.", "propagação de mensagens com objetivos políticos."]'::jsonb),
('2025-13',2025,13,8,'Variação linguística','O emprego da norma-padrão é justificado nesse texto','["pela especialização de seu público-alvo.", "pela relevância cultural de seu conteúdo.", "pelos contextos pedagógicos em que circula.", "pela importância para os grupos étnico-raciais.", "pelas características do gênero a que pertence."]'::jsonb),
('2025-14',2025,14,8,'Arte e identidade','Nesse trecho, ao se referir à sua filha, o pai de Inocência reproduz os ideais românticos, presentes na','["valorização do ambiente rural na formação moral da mulher.", "figura decorativa da mulher ante o protagonismo masculino.", "equivalência de origem social para a harmonia do casal.", "importância do dote como condição para o casamento.", "aura de mistério sobre a identidade da jovem."]'::jsonb),
